import {createViewState} from './ui-state.js';
import {stampCardView,stamps,themes,uid,balance,earned,eligibility,addEvent,makePin,verifyPin,encryptBackup,decryptBackup,newState} from './core.js';
import {initStore,saveState,recoverStore,ownWriter} from './storage.js';
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon=(name,size=20)=>{const p={grid:'<rect x="3" y="3" width="7" height="7" rx="2"/><rect x="14" y="3" width="7" height="7" rx="2"/><rect x="3" y="14" width="7" height="7" rx="2"/><rect x="14" y="14" width="7" height="7" rx="2"/>',gift:'<rect x="3" y="8" width="18" height="4" rx="1"/><path d="M5 12v9h14v-9M12 8v13M12 8H8a3 3 0 1 1 3-3l1 3Zm0 0h4a3 3 0 1 0-3-3l-1 3Z"/>',clock:'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/>',settings:'<path d="m9 3-1 3-3 1-2 3 2 2-1 4 3 2 3-1 3 3 3-1 1-3 3-1 1-4-3-2-1-4-4-1-2 2Z"/><circle cx="12" cy="12" r="3"/>',lock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 8 0v3M12 14v3"/>',unlock:'<rect x="5" y="10" width="14" height="11" rx="3"/><path d="M8 10V7a4 4 0 0 1 7-2M12 14v3"/>',plus:'<path d="M12 5v14M5 12h14"/>',minus:'<path d="M5 12h14"/>',arrow:'<path d="M5 12h14m-5-5 5 5-5 5"/>',chevron:'<path d="m9 5 7 7-7 7"/>',check:'<path d="m5 12 4 4L19 6"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',help:'<circle cx="12" cy="12" r="9"/><path d="M9.5 9a2.5 2.5 0 1 1 3.5 2.3c-1 .4-1 1-1 2M12 17h.01"/>',leaf:'<path d="M20 3C10 2 2 6 4 14s16 7 16-11ZM4 20 16 8"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',upload:'<path d="M12 16V4m-4 4 4-4 4 4M4 16v5h16v-5"/>',edit:'<path d="m15 4 5 5M4 20l5-1L21 7l-4-4L5 15l-1 5Z"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5L12 2Z"/>',shield:'<path d="m12 3 8 3v6c0 5-8 9-8 9s-8-4-8-9V6l8-3Z"/><path d="m8 12 3 3 5-6"/>',palette:'<path d="M12 3a9 9 0 1 0 0 18c3 0 1-4 4-4h2c6-3 3-14-6-14Z"/><path d="M7 9h.01M11 6h.01M16 8h.01M6 14h.01"/>',menu:'<path d="M4 6h16M4 12h16M4 18h16"/>'};return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${p[name]||p.spark}</svg>`};
let submitting=false;
let draftStamp=null,rewardFilter='all',historyFilter='all';
const cardPages=new Map();
let state,selected,page='home',sessionUntil=0,busy=false,modalType='',authCallback=null,recovery=false;
const app=$('#app');
const viewState=createViewState(document,globalThis.window||{});
const pageKey=()=>page+':'+(active()?.id||'family');
function navigate(next){viewState.savePage(pageKey());page=next;render({preserve:false});viewState.restorePage(pageKey());}
const active=()=>state.children.find(c=>c.id===selected)||state.children[0];
const theme=()=>themes.find(t=>t.id===active()?.theme)||themes[0];
const unlocked=()=>sessionUntil>Date.now();
const fmt=at=>new Intl.DateTimeFormat('zh-TW',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'}).format(new Date(at));
const childStampNames={star:'小星星',heart:'愛心',clover:'幸運草',flower:'小花',bear:'小熊',smile:'笑臉'};
const pic=(name,cls='',alt='')=>`<img class="${cls}" src="assets/${name}.png" alt="${esc(alt)}" draggable="false">`;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>$('#toast').classList.remove('show'),3500)}
async function mutate(fn){if(busy)throw Error('正在儲存，請稍候');busy=true;const old=structuredClone(state);try{fn(state);await saveState(state);}catch(e){state=old;throw e;}finally{busy=false;}render();}
function modal(title,body,{wide=false,subtitle='',child=false}={}){
 modalType=title;viewState.openDialog();
 $('#modal-root').innerHTML=`<div class="modal-overlay"><section class="modal ${wide?'wide':''} ${child?'child-dialog':''}" role="dialog" aria-modal="true" aria-labelledby="modal-title" tabindex="-1" data-scroll-key="dialog"><button class="icon-btn modal-close" data-action="close" aria-label="關閉">${icon('close',25)}</button><div class="modal-mark">${icon('spark',25)}</div><h2 id="modal-title">${title}</h2>${subtitle?`<p class="modal-sub">${subtitle}</p>`:''}${body}<div id="form-error" class="form-error" role="alert"></div></section></div>`;
 document.body.classList.add('modal-open');queueMicrotask(()=>viewState.focusNoScroll($('#modal-root .modal')));
}
function closeModal(){
 $('#modal-root').innerHTML='';document.body.classList.remove('modal-open');modalType='';authCallback=null;viewState.closeDialog();
}
function formError(e){const el=$('#form-error');if(el)el.textContent=e.message||String(e);else toast(e.message||String(e));}
async function requireParent(cb){if(unlocked()){await cb();return;}authCallback=cb;const setup=!state?.pin;modal(setup?'先設定家長密碼':'家長的小小通關密語',`<form id="auth-form"><label>${setup?'設定 4～8 位數字密碼':'輸入家長密碼（可加前後干擾數字）'}<input id="pin-input" type="password" inputmode="numeric" pattern="[0-9]*" minlength="4" maxlength="${setup?8:32}" autocomplete="${setup?'new-password':'off'}" required placeholder="${setup?'設定一組只有家長知道的密碼':'••••••'}"></label>${setup?'<label>再輸入一次密碼<input id="pin-confirm" type="password" inputmode="numeric" maxlength="8" autocomplete="new-password" required placeholder="確認密碼"></label>':''}<div class="soft-note">${icon('shield',18)}<span>${setup?'之後可在密碼前後加入任意數字，連續包含正確密碼就能通過。請記住密碼，系統無法找回。':'支援虛位密碼。連續輸錯 5 次會暫停輸入 1 分鐘，之後暫停時間逐步增加。'}</span></div><button class="btn primary full" type="submit">${icon(setup?'shield':'unlock')}${setup?'設定密碼並繼續':'解鎖家長模式'}</button></form>`,{subtitle:setup?'讓鼓勵自由發生，也讓每一顆星星安心被保護。':'解鎖後可操作 5 分鐘，隨時可以再上鎖。'});
 // modal() does not clear callback.
 authCallback=cb;
}
function header(){return `<header class="player-header"><div class="playground-wordmark"><span aria-hidden="true">✿</span> 小小集點園</div><p>今天誰要收集小星星？</p>${childTabs()}</header>`;}
function childTabs(){return `<div class="children-tabs" data-scroll-key="children" role="group" aria-label="選擇孩子">${state.children.map(c=>`<button class="child-tab ${active()?.id===c.id?'selected':''}" data-action="select-child" data-id="${c.id}" aria-pressed="${active()?.id===c.id}" style="--tab-color:${themes.find(t=>t.id===c.theme).color}"><span class="child-portrait">${pic('avatar-'+c.avatar,'child-avatar')}${active()?.id===c.id?`<span class="child-check">${icon('check',14)}</span>`:''}</span><span>${esc(c.name)}<small>✦ ${balance(state,c.id)}</small></span></button>`).join('')}<button class="add-child" data-action="add-child" aria-label="新增孩子"><span>${icon('plus',24)}</span>新夥伴</button></div>`;}
function historyRows(events,limit=0){const list=limit?events.slice(0,limit):events;return list.length?list.map(e=>{const c=state.children.find(c=>c.id===e.childId);return `<div class="history-row"><span class="history-stamp ${e.kind==='spend'?'minus-stamp':''}">${e.kind==='spend'?icon('minus'):e.kind==='redeem'?icon('gift'):pic('stamp-'+e.stamp)}</span><div class="history-info"><strong>${esc(e.kind==='redeem'?`兌換了「${e.rewardName}」`:e.reason|| (e.kind==='earn'?'今天也很棒，送你一個鼓勵！':'調整了小星星點數'))}</strong><small>${esc(c?.name||'孩子')} <span>·</span> ${fmt(e.at)}${e.kind==='redeem'&&e.reason?' · '+esc(e.reason):''}</small></div><span class="history-points ${e.delta<0?'negative':''}">${e.delta>0?'+':''}${e.delta} <small>點</small></span></div>`}).join(''):`<div class="empty-mini">${icon('leaf',26)}<p>第一個小努力，等著被記錄。</p></div>`;}
function collectionThumbnails(c,view){
 const pages=view.pageCount<=5?Array.from({length:view.pageCount},(_,i)=>i):[...new Set([0,view.pageCount-1,view.page-1,view.page,view.page+1].filter(i=>i>=0&&i<view.pageCount))].sort((a,b)=>a-b);
 let previous=-1;
 return `<aside class="collection-shelf" aria-label="我的小卡收藏"><button class="book-turn previous" data-action="card-page" data-page="${view.page-1}" ${view.page===0?'disabled':''} aria-label="上一張集點卡" title="上一張集點卡">${icon('chevron',28)}</button><div class="collection-thumbnails" data-scroll-key="cards-${c.id}" role="group" aria-label="選擇收藏的集點卡">${pages.map(p=>{
  const card=stampCardView(state,c.id,p),complete=card.points.length===20,gap=previous>=0&&p-previous>1;previous=p;
  return `${gap?'<span class="collection-gap" aria-hidden="true">•••</span>':''}<button class="collection-thumb ${p===view.page?'selected':''}" data-action="card-page" data-page="${p}" aria-pressed="${p===view.page}" aria-label="第 ${p+1} 張卡，${complete?'已集滿':`已有 ${card.points.length} 顆星星`}"><span class="mini-card" aria-hidden="true"><span class="mini-card-top">${pic('avatar-'+c.avatar)}<i>✦</i></span><span class="mini-card-grid">${Array.from({length:20},(_,i)=>`<i class="${i<card.points.length?'has-stamp':''}" ${i<card.points.length?`style="background-image:url('assets/stamp-${card.points[i].stamp}.png')"`:''}></i>`).join('')}</span>${pic('card-badge-'+(complete?'complete':'growing'),'mini-card-badge')}</span>${p===view.page?'<i class="thumb-selected">'+icon('check',17)+'</i>':''}</button>`;
 }).join('')}</div><button class="book-turn next" data-action="card-page" data-page="${view.page+1}" ${view.page===view.pageCount-1?'disabled':''} aria-label="下一張集點卡" title="下一張集點卡">${icon('chevron',28)}</button><span class="sr-only">第 ${view.page+1} / ${view.pageCount} 張</span></aside>`;
}
function stampCard(){
 const c=active(),view=stampCardView(state,c.id,cardPages.get(c.id)),{total,offset}=view,filled=view.points.length,last=view.points,picked=draftStamp||c.stamp;
 return `<section class="stamp-playground" aria-labelledby="stamp-card-title"><div class="card-with-rail"><div class="collection-book ${view.pageCount>1?'has-other-cards':''}"><div class="stamp-sheet"><div class="notebook-tape" aria-hidden="true"></div><div class="game-card-heading"><div><h2 id="stamp-card-title">我的小星星卡 <span aria-hidden="true">✦</span></h2></div><div class="game-point-count"><strong>${total}</strong><span>顆小星星</span></div></div><div class="sheet-owner">${pic('avatar-'+c.avatar)}<span>${esc(c.name)}的寶貝卡片</span><span class="sheet-range">${offset+1}～${offset+20}</span></div><div class="game-progress"><div class="game-progress-track" role="progressbar" aria-label="這張集點卡的進度" aria-valuemin="0" aria-valuemax="20" aria-valuenow="${filled}"><i style="width:${filled*5}%"></i></div><span>${filled} <small>/ 20</small></span></div><div class="game-stamp-grid" aria-label="第 ${view.page+1} 張集點卡，20 格中已收集 ${filled} 格">${Array.from({length:20},(_,i)=>{
 const stamp=last[i]?.stamp||c.stamp,number=offset+i+1;
 return i<filled?`<button class="game-stamp-slot filled" data-action="stamp-details" data-index="${i}" data-stamp-number="${number}" aria-label="第 ${number} 顆小星星，查看得章紀錄" style="--rotation:${[-9,5,-5,8,-3][i%5]}deg">${pic('stamp-'+stamp,'earned-stamp',stamps.find(s=>s.id===stamp).name)}</button>`:`<button class="game-stamp-slot empty ${i===filled?'next-slot':''}" data-action="stamp" data-kind="earn" data-stamp-number="${number}" aria-label="第 ${number} 格，請家長幫忙蓋章"><span class="slot-number" data-digits="${String(number).length}">${number}</span>${i===filled?'<span class="next-label">蓋章</span>':''}</button>`;
 }).join('')}</div></div></div>${collectionThumbnails(c,view)}</div><div class="game-stamp-picker"><div class="picker-heading"><span class="step-dot">1</span><h3>想蓋哪個章？</h3><span>自己選一個吧！</span></div><div class="game-stamp-options" role="group" aria-label="選擇這次的圖片印章">${stamps.map(stamp=>`<button class="stamp-choice ${picked===stamp.id?'picked':''}" data-action="pick-stamp" data-stamp="${stamp.id}" aria-pressed="${picked===stamp.id}">${pic('stamp-'+stamp.id,'',stamp.name)}<span>${childStampNames[stamp.id]}</span>${picked===stamp.id?`<i>${icon('check',18)}</i>`:''}</button>`).join('')}</div></div><div class="game-stamp-action"><span class="step-dot">2</span><div class="stamp-call-to-action"><button class="btn stamp-main-button" data-action="stamp" data-kind="earn">${pic('stamp-'+picked)}<span>幫我蓋章！</span>${icon('spark',28)}</button><p>${icon(unlocked()?'unlock':'lock',18)} ${unlocked()?'家長解鎖了，可以蓋章囉！':'請家長幫忙，蓋下今天的努力'}</p></div></div></section>`;
}
function rewardQuest(){
 const c=active();if(!c)return '';
 const options=state.rewards.map(r=>({r,e:eligibility(state,c.id,r)})).filter(x=>!x.e.claimed).sort((a,b)=>Number(b.e.ready)-Number(a.e.ready)||Math.max(0,a.r.cost-a.e.current)-Math.max(0,b.r.cost-b.e.current));
 const next=options[0];
 return `<section class="reward-quest" aria-label="下一個期待的小獎勵">${next?`${pic('reward-'+next.r.image,'quest-art')}<div class="quest-copy"><span>我的下一個小期待</span><h2>${esc(next.r.name)}</h2><p>${next.e.ready?'已經達成了！快和家長一起領獎吧！':`再收集 ${Math.max(0,next.r.cost-next.e.current)} 顆小星星，就可以實現囉！`}</p></div><button class="btn quest-button" data-action="${next.e.ready?'redeem':'page'}" ${next.e.ready?`data-id="${next.r.id}"`:'data-page="rewards"'}>${next.e.ready?'領取小獎勵':'看看小獎勵'} ${icon('arrow',18)}</button>`:`${pic('reward-gift','quest-art')}<div class="quest-copy"><span>把快樂放進期待裡</span><h2>一起約定下一個小獎勵</h2><p>一場野餐、一個擁抱，都很棒！</p></div><button class="btn quest-button" data-action="add-reward">一起訂獎勵 ${icon('plus',18)}</button>`}</section>`;
}
const rewardModes=[{id:'spend',name:'扣點兌換',image:'icecream',description:'用小星星，換一份快樂',note:'用目前餘額兌換獎勵，兌換時扣點，可重複兌換。'},{id:'card',name:'集滿卡片',image:'game',description:'每集滿一次，就慶祝一次',note:'每累積指定點數可領取一次，不扣目前餘額；已用過的累積點數不重複計算。'},{id:'milestone',name:'成長里程碑',image:'gift',description:'累積努力，解鎖大驚喜',note:'累積獲得點數達標即可領取，不扣目前餘額，每位孩子限領一次。'}];
function rewardEntrances(){return `<section class="reward-play-modes" aria-labelledby="reward-modes-title"><div class="reward-modes-heading"><h2 id="reward-modes-title">${icon('gift',23)} 我的小獎勵</h2><button data-action="page" data-page="rewards">全部小獎勵 ${icon('chevron',17)}</button></div><div class="reward-mode-cards">${rewardModes.map(m=>`<button data-action="page" data-page="rewards" data-rule="${m.id}">${pic('reward-'+m.image)}<span><strong>${m.name}</strong><small>${m.description}</small></span>${icon('chevron',17)}</button>`).join('')}</div></section>`;}
function home(){
 const c=active();
 if(!c)return `<section class="empty-state"><div class="empty-garden">${pic('garden-friends','', '小熊和兔子等著新夥伴')}</div><h1>這裡，留了一個位置給你！</h1><p>選一位可愛夥伴，開始收集自己的小星星。</p><button class="btn primary" data-action="add-child">${icon('plus',22)} 加入第一位小夥伴</button></section>`;
 return `<section class="game-greeting"><div class="greeting-copy"><span class="theme-caption">${theme().emoji} ${theme().name}<button class="theme-switch" data-action="theme" aria-label="換個小天地" title="換個小天地">${icon('palette',24)}</button></span><h1>${esc(c.name)}，今天也很棒！</h1><p>${theme().caption}</p></div>${pic('garden-friends','greeting-friends','小熊和兔子陪你收集小星星')}</section>${stampCard()}${rewardEntrances()}${rewardQuest()}<div class="little-memories"><button data-action="page" data-page="history">${icon('clock',19)} 我的成長足跡 ${icon('chevron',15)}</button><p>每一份努力，我們都有看見 <span>♡</span></p></div>`;
}
const ruleName=r=>({spend:'扣點兌換',card:'集滿卡片',milestone:'成長里程碑'}[r]);
function rewardPage(){const visible=state.rewards.filter(r=>rewardFilter==='all'||r.rule===rewardFilter),mode=rewardModes.find(m=>m.id===rewardFilter);return `<div class="page-heading"><span class="eyebrow">HAPPY LITTLE REWARDS</span><h1>獎勵小舖 <span>🎁</span></h1><p>最棒的獎勵，是和你一起的快樂時光。</p></div><div class="reward-filters" role="group" aria-label="選擇兌獎玩法">${[{id:'all',name:'全部小獎勵'},...rewardModes].map(m=>`<button data-action="reward-filter" data-rule="${m.id}" aria-pressed="${rewardFilter===m.id}">${m.name}<span>${state.rewards.filter(r=>m.id==='all'||r.rule===m.id).length}</span></button>`).join('')}</div>${mode?`<p class="reward-rule-note">${icon('spark',18)} ${mode.note}</p>`:''}<div class="page-toolbar"><span>一起期待的 ${visible.length} 個小目標</span><button class="btn primary" data-action="add-reward">${icon('plus',17)} 新增獎勵</button></div><div class="reward-grid">${visible.map(r=>{const e=active()?eligibility(state,active().id,r):null;return `<article class="reward-full panel"><div class="reward-image ${r.image}">${pic('reward-'+r.image)}<span class="rule-badge">${ruleName(r.rule)}</span><button class="icon-btn" data-action="edit-reward" data-id="${r.id}" aria-label="編輯${esc(r.name)}">${icon('edit',17)}</button></div><div class="reward-full-body"><h2>${esc(r.name)}</h2><p>${esc(r.description)}</p><div class="reward-full-cost">${r.cost} <small>顆小星星</small></div><p class="rule-detail">${r.rule==='spend'?'兌換時扣除點數，可重複兌換':r.rule==='card'?'每累積指定點數可兌換一次，不扣餘額':'累積獲得指定點數，每位孩子限領一次'}</p>${e?`<div class="reward-progress"><i style="width:${Math.min(100,e.current/r.cost*100)}%"></i></div><div class="reward-status">${e.claimed?'已解鎖這個里程碑！':`目前 ${e.current} / ${r.cost} 點`}</div><button class="btn ${e.ready?'primary':'secondary'} full" data-action="redeem" data-id="${r.id}" ${!e.ready?'disabled':''}>${e.claimed?icon('check')+' 已領取':e.ready?icon('gift')+' 兌換這份快樂':'再 '+Math.max(0,r.cost-e.current)+' 點就達成囉'}</button>`:'<p>先新增一位孩子，就能開始兌獎。</p>'}</div></article>`}).join('')||`<div class="reward-empty">${pic('reward-gift')}<h2>一起訂下第一個小獎勵</h2><p>${mode?`「${mode.name}」還沒有獎勵，和家長一起決定一個吧！`:'一段遊戲時光、一場公園探險，都值得期待。'}</p><button class="btn primary" data-action="add-reward">${icon('plus',19)} 一起訂獎勵</button></div>`}</div>`;}
function historyPage(){const c=active();return `<div class="page-heading"><span class="eyebrow">EVERY LITTLE STEP COUNTS</span><h1>小小成長紀錄</h1><p>把努力留下來，有一天回頭看，會發現自己走了好遠。</p></div>${c?`<div class="history-stats"><div class="panel"><span>目前擁有</span><strong>${balance(state,c.id)}<small>點</small></strong></div><div class="panel"><span>累積努力</span><strong>${earned(state,c.id)}<small>點</small></strong></div><div class="panel"><span>快樂兌獎</span><strong>${state.events.filter(e=>e.childId===c.id&&e.kind==='redeem').length}<small>次</small></strong></div></div><section class="panel history-list"><div class="history-filters"><h2>${esc(c.name)}的成長足跡</h2><select id="history-filter" aria-label="篩選紀錄"><option value="all" ${historyFilter==='all'?'selected':''}>全部紀錄</option><option value="earn" ${historyFilter==='earn'?'selected':''}>獲得鼓勵</option><option value="spend" ${historyFilter==='spend'?'selected':''}>消點調整</option><option value="redeem" ${historyFilter==='redeem'?'selected':''}>兌換獎勵</option></select></div><div id="history-entries">${historyRows(state.events.filter(e=>e.childId===c.id&&(historyFilter==='all'||e.kind===historyFilter)).slice().reverse())}</div></section>`:'<div class="panel empty-state">先新增孩子，開始記錄每一步成長。</div>'}`;}
function settingsPage(){return `<div class="page-heading"><span class="eyebrow">OUR LITTLE FAMILY</span><h1>家庭設定</h1><p>把小天地整理好，放心陪孩子一起長大。</p></div><div class="settings-layout"><section class="panel setting-section"><h2>${icon('lock')} 家長保護</h2><div class="setting-row"><div><h3>家長蓋章密碼</h3><p>${state.pin?'已設定密碼 · 支援前後加數字的虛位密碼':'尚未設定。第一次進行家長操作時，會引導設定。'}</p></div><button class="btn secondary" data-action="change-pin">${state.pin?'更改密碼':'設定密碼'}</button></div><div class="setting-row"><div><h3>自動上鎖</h3><p>解鎖 5 分鐘後自動上鎖，離開頁面也會立即上鎖。</p></div><span class="status-badge">${icon('check',14)} 已啟用</span></div><div class="info-note">虛位密碼可降低旁人看出密碼的機會；仍請遮擋輸入，避免重複使用同樣的前後數字。</div></section><section class="panel setting-section"><h2>${icon('grid')} 孩子的專屬手冊</h2>${state.children.map(c=>`<div class="setting-row"><div class="child-setting-info">${pic('avatar-'+c.avatar)}<div><h3>${esc(c.name)}</h3><p>${themes.find(t=>t.id===c.theme).name} · ${balance(state,c.id)} 點</p></div></div><button class="btn secondary" data-action="edit-child" data-id="${c.id}">編輯手冊</button></div>`).join('')}<button class="add-reward-small" data-action="add-child">${icon('plus',17)} 新增孩子</button></section><section class="panel setting-section"><h2>${icon('shield')} 安心備份</h2><p class="setting-description">資料存在目前瀏覽器的 IndexedDB，不會自動同步到其他裝置。清除瀏覽器資料前，請先匯出備份。</p><div class="backup-options"><button data-action="export">${icon('download',24)}<strong>匯出加密備份</strong><span>把小小回憶，安心收藏</span></button><button data-action="import">${icon('upload',24)}<strong>匯入加密備份</strong><span>換台裝置，接著一起長大</span></button></div><div class="info-note">備份採用 AES-256-GCM 加密與驗證，檔案被修改將無法開啟。請另外保管備份密碼，忘記後無法還原。舊的有效備份仍可匯入，純本機系統無法完全防止資料回溯。</div></section></div>`;}
function parentTools(){modal('家長小幫手',`<div class="parent-tool-menu"><p>孩子負責期待，大人負責守護。</p><button data-action="parent">${icon(unlocked()?'lock':'unlock',22)}<span>${unlocked()?'先把家長模式上鎖':'解鎖家長模式'}<small>${unlocked()?'收好今天的鼓勵':'蓋章、消點前需輸入家長密碼'}</small></span>${icon('chevron',18)}</button><button data-action="open-rewards">${icon('gift',22)}<span>設定獎勵與兌獎規則<small>扣點兌換、集滿卡片、成長里程碑</small></span>${icon('chevron',18)}</button><button data-action="open-settings">${icon('settings',22)}<span>整理我們的小天地<small>孩子、密碼與加密備份</small></span>${icon('chevron',18)}</button><button data-action="parent-spend">${icon('minus',22)}<span>調整小星星點數<small>消點也會保留紀錄</small></span>${icon('chevron',18)}</button><button data-action="help">${icon('help',22)}<span>一起看使用說明<small>了解集點、兌獎和資料保護</small></span>${icon('chevron',18)}</button>${state.demo?'<button class="start-family-tool" data-action="start-family">'+icon('leaf',22)+'<span>開始我的家庭<small>清除體驗手冊，建立自己的家庭</small></span>'+icon('chevron',18)+'</button>':''}</div>`);}
function render({preserve=true}={}){
 if(!state)return;const viewport=preserve?viewState.capture():null;if(preserve&&app.getBoundingClientRect)app.style.minHeight=Math.max(parseFloat(app.style.minHeight)||0,app.getBoundingClientRect().height)+'px';else if(!preserve)app.style.minHeight='';const t=theme();document.documentElement.style.setProperty('--accent',t.color);document.documentElement.style.setProperty('--tint',t.light);
 app.innerHTML=`<div class="game-shell" data-theme="${t.id}">${header()}<main class="game-main ${page==='home'?'at-home':'secondary-screen'}">${page!=='home'?`<button class="back-to-game" data-action="home">${icon('arrow',18)} 回去蓋章</button>`:''}${({home,rewards:rewardPage,history:historyPage,settings:settingsPage}[page])()}</main><footer class="game-footer"><span>用愛陪伴，用鼓勵長大 <span aria-hidden="true">✿</span></span><div>${state.demo?'<span class="demo-family">體驗家庭</span>':''}<button id="parent-mode" data-action="parent-tools">${icon(unlocked()?'unlock':'lock',16)} 家長小幫手${unlocked()?'<i class="parent-unlocked-dot" aria-label="已解鎖"></i>':''}</button></div></footer></div>`;
 if(viewport)viewState.restore(viewport);
}
function childForm(c=null){modal(c?'編輯專屬手冊':'新增一位小小探險家',`<form id="child-form" data-id="${c?.id||''}"><label>孩子的名字<input name="name" maxlength="20" required placeholder="例如：小米" value="${esc(c?.name||'')}"></label><fieldset><legend>選一位可愛夥伴</legend><div class="avatar-options">${['bear','bunny','cat','fox'].map((a,i)=>`<label class="image-option"><input type="radio" name="avatar" value="${a}" ${(c?.avatar||'bear')===a?'checked':''}>${pic('avatar-'+a,'',['小熊','兔子','貓咪','狐狸'][i])}</label>`).join('')}</div></fieldset><fieldset><legend>喜歡什麼小天地？</legend><div class="theme-options">${themes.map(t=>`<label class="theme-option" style="--option-bg:${t.light};--option-color:${t.color}"><input type="radio" name="theme" value="${t.id}" ${(c?.theme||'forest')===t.id?'checked':''}><span>${t.emoji}</span>${t.name}</label>`).join('')}</div></fieldset><button class="btn primary full">${icon('check')} ${c?'儲存手冊':'建立專屬手冊'}</button>${c?`<button type="button" class="danger-link" data-action="delete-child" data-id="${c.id}">刪除這本手冊與紀錄</button>`:''}</form>`,{subtitle:c?'每個孩子，都有自己喜歡的樣子。':'準備好了嗎？一起收集生活中的小美好。'});}
function themeForm(){const c=active();if(!c)return;modal('今天想去哪個小天地？',`<div class="theme-picks">${themes.map(t=>`<button style="--option-bg:${t.light};--option-color:${t.color}" data-action="choose-theme" data-theme="${t.id}"><span>${t.emoji}</span><strong>${t.name}</strong><small>${t.caption}</small>${c.theme===t.id?icon('check'):''}</button>`).join('')}</div>`,{child:true});}
function stampForm(kind){const c=active();if(!c)return;modal(kind==='earn'?'給努力的你，一個鼓勵':'調整小星星點數',`<form id="stamp-form" data-kind="${kind}"><div class="stamp-child">${pic('avatar-'+c.avatar)}<span>${esc(c.name)}<small>目前有 ${balance(state,c.id)} 顆小星星</small></span></div><label>${kind==='earn'?'這次要給幾點鼓勵？':'這次要消除幾點？'}<div class="stepper"><button type="button" data-action="step" data-step="-1" aria-label="減少一點">${icon('minus')}</button><input name="amount" id="stamp-amount" type="number" min="1" max="${kind==='earn'?999:Math.min(999,balance(state,c.id))}" value="1" required inputmode="numeric"><button type="button" data-action="step" data-step="1" aria-label="增加一點">${icon('plus')}</button><span>點</span></div></label>${kind==='earn'?`<fieldset><legend>挑一個喜歡的印章</legend><div class="stamp-options">${stamps.map(s=>`<label class="image-option"><input type="radio" name="stamp" value="${s.id}" ${(draftStamp||c.stamp)===s.id?'checked':''}>${pic('stamp-'+s.id,'',s.name)}</label>`).join('')}</div></fieldset>`:''}<label>${kind==='earn'?'記下今天的小努力':'記下調整原因'}<span class="optional">選填</span><textarea name="reason" maxlength="120" rows="2" placeholder="${kind==='earn'?'例如：今天主動把玩具收好了！':'例如：剛剛多蓋了一個章'}"></textarea></label>${kind==='earn'?'<div class="reason-chips">'+['自己收好玩具','主動幫忙','認真閱讀','勇敢嘗試'].map(r=>`<button type="button" data-action="reason" data-reason="${r}">${r}</button>`).join('')+'</div>':''}<button class="btn primary full" ${kind==='spend'&&balance(state,c.id)<1?'disabled':''}>${icon(kind==='earn'?'plus':'minus')} ${kind==='earn'?'蓋下滿滿的鼓勵':'確認消點'}</button></form>`,{subtitle:kind==='earn'?'讓孩子知道，你的每一份努力，我都有看見。':'每次調整都會保留紀錄。'});}
function rewardForm(r=null){modal(r?'編輯期待的小獎勵':'一起訂一個新獎勵',`<form id="reward-form" data-id="${r?.id||''}"><label>獎勵名稱<input name="name" maxlength="40" required value="${esc(r?.name||'')}" placeholder="例如：一起去公園野餐"></label><label>一小段期待的話 <span class="optional">選填</span><input name="description" maxlength="120" value="${esc(r?.description||'')}" placeholder="和孩子一起決定喜歡的獎勵"></label><fieldset><legend>選一個可愛圖案</legend><div class="reward-icon-options">${['icecream','game','gift','book','park','movie'].map((a,i)=>`<label class="image-option"><input type="radio" name="image" value="${a}" ${(r?.image||'gift')===a?'checked':''}>${pic('reward-'+a,'',['冰淇淋','遊戲','禮物','故事書','公園','電影'][i])}</label>`).join('')}</div></fieldset><label>兌獎方式<select name="rule" id="reward-rule">${[['spend','扣點兌換 · 用目前點數換獎勵'],['card','集滿卡片 · 每集滿一次就能領取，不扣點'],['milestone','成長里程碑 · 累積達標，一人限領一次']].map(([v,l])=>`<option value="${v}" ${(r?.rule||(rewardFilter==='all'?'spend':rewardFilter))===v?'selected':''}>${l}</option>`).join('')}</select></label><label>需要幾點？<input name="cost" type="number" inputmode="numeric" min="1" max="999" value="${r?.cost||10}" required></label>${r?'<div class="info-note">已有兌換紀錄的獎勵會保留原規則與門檻；如要改變，請新增另一個獎勵。</div>':''}<button class="btn primary full">${icon('gift')} ${r?'儲存獎勵':'加入期待清單'}</button>${r?`<button type="button" class="danger-link" data-action="delete-reward" data-id="${r.id}">移除這個獎勵</button>`:''}</form>`,{subtitle:'不一定要買東西，一段專屬的陪伴也很棒。'});}
function redeemForm(id){const r=state.rewards.find(r=>r.id===id),c=active();if(!r||!c)return;if(!eligibility(state,c.id,r).ready){toast('再努力一點，就快達成囉！');return;}modal('耶！小努力變成小快樂',`<form id="redeem-form" data-id="${r.id}"><div class="redeem-illustration">${pic('reward-'+r.image)}</div><h3 class="center">${esc(r.name)}</h3><p class="center muted">${esc(c.name)}，這是你的努力換來的！</p><div class="soft-note">${icon('gift')}<span>${r.rule==='spend'?`這次會扣除 ${r.cost} 點，兌換後剩下 ${balance(state,c.id)-r.cost} 點。`:r.rule==='card'?`使用一張 ${r.cost} 點累積卡，不扣除目前點數。`:'達成成長里程碑！每位孩子可領取一次，不扣除目前點數。'}</span></div><label>一起留下快樂的話 <span class="optional">選填</span><input name="reason" maxlength="120" placeholder="例如：週末一起去吃吧！"></label><button class="btn primary full">${icon('gift')} 確認兌換獎勵</button></form>`,{child:true});}
function backupForm(mode){modal(mode==='export'?'把小小回憶，安心收藏':'讓成長回憶接著延續',`<form id="backup-form" data-mode="${mode}">${mode==='import'?'<label>選擇 .garden 加密備份<input name="file" type="file" accept=".garden,.json,application/json" required></label>':''}<label>${mode==='export'?'設定這份備份的密碼':'輸入備份密碼'}<input type="password" name="password" minlength="8" maxlength="128" required autocomplete="${mode==='export'?'new-password':'off'}" placeholder="至少 8 個字元，請妥善保存"></label>${mode==='export'?'<label>確認備份密碼<input type="password" name="confirm" minlength="8" maxlength="128" required autocomplete="new-password" placeholder="再輸入一次備份密碼"></label>':'<label>備份中的家長密碼<input type="password" name="pin" inputmode="numeric" maxlength="32" required placeholder="支援前後干擾數字"></label><label class="checkbox-label"><input type="checkbox" name="replace" required>我知道匯入會取代目前全部孩子、獎勵與紀錄</label>'}<div class="soft-note">${icon('shield')}<span>${mode==='export'?'檔案會經過加密與完整性驗證。備份密碼與家長密碼可以不同，兩組都要記得喔。':'會先驗證加密檔與資料格式，成功後才一次取代資料。建議先匯出目前資料留存。'}</span></div><button class="btn primary full">${icon(mode==='export'?'download':'upload')} ${mode==='export'?'下載加密備份':'驗證並匯入備份'}</button></form>`);}
function help(){modal('小小集點園使用指南',`<div class="help-content"><h3>① 建立你們的小天地</h3><p>在上方點選自己的可愛夥伴。第一次使用可到「家長小幫手」選「開始我的家庭」，清除體驗手冊，再新增孩子。</p><h3>② 給努力一個鼓勵</h3><p>孩子先在首頁挑選喜歡的圖片印章，再點空白格或「幫我蓋一個章」。請家長解鎖後確認點數，原因可寫可不寫。每 20 點一張卡，可點小卡縮圖或前一張／後一張回看尚未使用的星星；點已蓋的印章可以看得章原因與時間。消點入口在「家長小幫手」。</p><h3>③ 一起約定小獎勵</h3><p>「扣點兌換」會扣除餘額；「集滿卡片」按累積獲得點數重複領獎；「成長里程碑」每位孩子只能領取一次。</p><h3>④ 密碼與備份</h3><p>虛位密碼的連續數字中包含正確密碼就能解鎖，最長 32 位。5 次錯誤會暫停，解鎖最多維持 5 分鐘，離開頁面立即上鎖。</p><p>資料只在這個瀏覽器，請定期匯出加密備份；換裝置時匯入，需備份密碼及備份中的家長密碼。密碼無法找回。</p><div class="info-note">本機資料以不可匯出的 HMAC 金鑰驗證。加密備份可偵測修改，但不能防止持有舊備份的人回溯資料，也無法防止能控制裝置與程式的人作弊。這是協助家庭互信的工具。</div><button class="btn primary full" data-action="close">知道了，一起開始吧！</button></div>`,{wide:true});}
async function action(el){const a=el.dataset.action;if(busy||submitting)return;viewState.rememberTrigger(el);
 if(a==='close'){closeModal();return;}
 if(a==='page'||a==='home'){const next=el.dataset.page||'home';if(next==='rewards')rewardFilter=rewardModes.some(m=>m.id===el.dataset.rule)?el.dataset.rule:'all';navigate(next);return;}
 if(a==='select-child'){selected=el.dataset.id;draftStamp=null;page='home';render();viewState.focusNoScroll($('.child-tab.selected'));return;}
 if(a==='card-page'){const c=active();if(!c)return;const next=stampCardView(state,c.id,Number(el.dataset.page));cardPages.set(c.id,next.page);render();viewState.focusNoScroll($('.collection-thumb.selected'));const strip=$('.collection-thumbnails'),thumb=$('.collection-thumb.selected');if(strip&&thumb){if(thumb.offsetTop<strip.scrollTop)strip.scrollTop=thumb.offsetTop;else if(thumb.offsetTop+thumb.offsetHeight>strip.scrollTop+strip.clientHeight)strip.scrollTop=thumb.offsetTop+thumb.offsetHeight-strip.clientHeight;}return;}
 if(a==='stamp-details'){const c=active();if(!c)return;const v=stampCardView(state,c.id,cardPages.get(c.id)),index=Number(el.dataset.index),point=v.points[index];if(!Number.isInteger(index)||!point)return;modal('第 '+(v.offset+index+1)+' 顆小星星',`<div class="stamp-record-detail">${pic('stamp-'+point.stamp,'',stamps.find(s=>s.id===point.stamp)?.name)}<h3>${esc(point.reason||'今天也很棒，送你一個鼓勵！')}</h3><p>${esc(c.name)} · ${fmt(point.at)}</p><button class="btn primary full" data-action="close">收好了</button></div>`,{child:true});return;}
 if(a==='pick-stamp'){if(!stamps.some(s=>s.id===el.dataset.stamp))return;draftStamp=el.dataset.stamp;render();viewState.focusNoScroll($('.stamp-choice.picked'));return;}
 if(a==='parent-tools'){parentTools();return;}
 if(a==='reward-filter'){rewardFilter=rewardModes.some(m=>m.id===el.dataset.rule)?el.dataset.rule:'all';render();return;}
 if(a==='open-rewards'){closeModal();await requireParent(()=>{rewardFilter='all';navigate('rewards');});return;}
 if(a==='open-settings'){closeModal();await requireParent(()=>{navigate('settings');});return;}
 if(a==='parent-spend'){closeModal();if(!active()){toast('先新增一位小夥伴吧');return;}await requireParent(()=>stampForm('spend'));return;}
 if(a==='help'){help();return;}
 if(a==='parent'){closeModal();if(unlocked()){sessionUntil=0;render();toast('家長模式已上鎖');}else await requireParent(()=>{render();toast('家長模式已開啟，5 分鐘後自動上鎖');});return;}
 if(a==='add-child'){await requireParent(()=>childForm());return;}
 if(a==='edit-child'){const c=state.children.find(c=>c.id===el.dataset.id)||active();await requireParent(()=>childForm(c));return;}
 if(a==='theme'){themeForm();return;}
 if(a==='choose-theme'){await mutate(s=>{s.children.find(c=>c.id===active().id).theme=el.dataset.theme;});closeModal();toast('換上新的小天地了！');return;}
 if(a==='stamp'){await requireParent(()=>stampForm(el.dataset.kind));return;}
 if(a==='step'){const inp=$('#stamp-amount');inp.value=Math.max(1,Math.min(Number(inp.max),Number(inp.value||1)+Number(el.dataset.step)));return;}
 if(a==='reason'){ $('textarea[name=reason]').value=el.dataset.reason;return;}
 if(a==='add-reward'){await requireParent(()=>rewardForm());return;}
 if(a==='edit-reward'){await requireParent(()=>rewardForm(state.rewards.find(r=>r.id===el.dataset.id)));return;}
 if(a==='redeem'){await requireParent(()=>redeemForm(el.dataset.id));return;}
 if(a==='export'||a==='import'){if(recovery){backupForm('import');return;}await requireParent(()=>backupForm(a));return;}
 if(a==='change-pin'){await requireParent(()=>modal('更改家長密碼','<form id="change-pin-form"><label>新的 4～8 位數字密碼<input name="pin" type="password" inputmode="numeric" minlength="4" maxlength="8" required autocomplete="new-password"></label><label>確認新密碼<input name="confirm" type="password" inputmode="numeric" minlength="4" maxlength="8" required autocomplete="new-password"></label><div class="soft-note">'+icon('lock')+'<span>新匯出的備份會使用新家長密碼；舊備份仍使用當時的密碼。</span></div><button class="btn primary full">儲存新密碼</button></form>'));return;}
 if(a==='delete-child'){const c=state.children.find(c=>c.id===el.dataset.id);modal('確定要和這本手冊道別嗎？',`<form id="delete-child-form" data-id="${c.id}"><p>將永久刪除「${esc(c.name)}」及其所有集點、兌獎紀錄。建議先匯出備份。</p><label>輸入孩子的名字確認<input name="confirm" required autocomplete="off" placeholder="${esc(c.name)}"></label><button class="btn danger full">刪除手冊與紀錄</button></form>`);return;}
 if(a==='delete-reward'){const r=state.rewards.find(r=>r.id===el.dataset.id);modal('移除這個小獎勵？',`<form id="delete-reward-form" data-id="${r.id}"><p>將移除「${esc(r.name)}」，之前兌換的紀錄會保留。</p><button class="btn danger full">確認移除獎勵</button></form>`);return;}
 if(a==='start-family'){await requireParent(()=>modal('準備建立自己的家庭囉！','<form id="start-family-form"><p>會清除小宇、小晴的體驗手冊與體驗紀錄，保留你設定的家長密碼和獎勵。新的孩子會從 0 點開始。</p><button class="btn primary full">清除體驗，新增我的孩子</button></form>'));}
}
async function submit(form){if(busy||submitting)return;submitting=true;const f=new FormData(form),id=form.id;let button=form.querySelector('button[type=submit], button:not([type])');if(button)button.disabled=true;
 try{
 if(id==='auth-form'){
  if(state.lockUntil>Date.now())throw Error(`請稍等 ${Math.ceil((state.lockUntil-Date.now())/1000)} 秒，再試一次。`);
  const input=$('#pin-input').value;
  if(!state.pin){if(input!==$('#pin-confirm').value)throw Error('兩次輸入的密碼不相同');const pin=await makePin(input);await mutate(s=>{s.pin=pin;});}
  else {const correct=await verifyPin(input,state.pin);if(!correct){await mutate(s=>{s.failures++;if(s.failures>=5)s.lockUntil=Date.now()+Math.min(900000,60000*2**Math.min(4,s.failures-5));});$('#pin-input').value='';throw Error(state.lockUntil>Date.now()?'為保護密碼，請稍後再試。':'密碼不正確，再試一次吧。');}await mutate(s=>{s.failures=0;s.lockUntil=0;});}
  sessionUntil=Date.now()+300000;const cb=authCallback;closeModal();render();if(cb)await cb();return;
 }
 // All privileged forms re-check the session at submission, not only when opening.
 if(!['backup-form'].includes(id)&&!unlocked())throw Error('家長模式已上鎖，請關閉視窗並重新解鎖。');
 if(id==='child-form'){const data={name:String(f.get('name')).trim(),avatar:f.get('avatar'),theme:f.get('theme')};if(!data.name)throw Error('幫孩子取一個名字吧');await mutate(s=>{if(form.dataset.id)Object.assign(s.children.find(c=>c.id===form.dataset.id),data);else{if(s.children.length>=50)throw Error('最多可建立 50 本手冊');const c={id:uid(),stamp:'star',...data};s.children.push(c);selected=c.id;draftStamp=null;}});closeModal();toast('專屬手冊準備好了！');}
 if(id==='stamp-form'){const c=active(),stamp=f.get('stamp')||c.stamp;if(form.dataset.kind==='earn'){draftStamp=stamp;cardPages.delete(c.id);}await mutate(s=>{addEvent(s,c.id,form.dataset.kind,Number(f.get('amount')),f.get('reason'),stamp);s.children.find(x=>x.id===c.id).stamp=stamp;});closeModal();toast(form.dataset.kind==='earn'?'蓋章成功！每一份努力都值得被看見 ✨':'點數已調整，紀錄已保存');if(form.dataset.kind==='earn')celebrate();}
 if(id==='reward-form'){const data={name:String(f.get('name')).trim(),description:String(f.get('description')||'').trim(),image:f.get('image'),rule:f.get('rule'),cost:Number(f.get('cost'))};if(!data.name)throw Error('為這份期待取個名字吧');await mutate(s=>{if(form.dataset.id){const r=s.rewards.find(r=>r.id===form.dataset.id);if(s.events.some(e=>e.rewardId===r.id)&&(r.rule!==data.rule||r.cost!==data.cost))throw Error('已有兌獎紀錄，請保留原規則與門檻，或新增另一個獎勵。');Object.assign(r,data);}else s.rewards.push({id:uid(),...data});});closeModal();toast('把期待放進獎勵小舖了！');}
 if(id==='redeem-form'){const r=state.rewards.find(r=>r.id===form.dataset.id);await mutate(s=>addEvent(s,active().id,'redeem',r.cost,f.get('reason'),active().stamp,r));closeModal();toast('兌換成功！一起享受這份快樂吧 🎉');celebrate();}
 if(id==='change-pin-form'){if(f.get('pin')!==f.get('confirm'))throw Error('兩次輸入的密碼不相同');const pin=await makePin(String(f.get('pin')));if(!unlocked())throw Error('家長模式已上鎖，請重新解鎖。');await mutate(s=>{s.pin=pin;s.failures=0;s.lockUntil=0;});sessionUntil=0;render();closeModal();toast('家長密碼已更新，請使用新密碼解鎖');}
 if(id==='delete-child-form'){const c=state.children.find(c=>c.id===form.dataset.id);if(f.get('confirm')!==c.name)throw Error('請輸入完整的孩子名字');await mutate(s=>{s.children=s.children.filter(x=>x.id!==c.id);s.events=s.events.filter(e=>e.childId!==c.id);});selected=state.children[0]?.id;draftStamp=null;closeModal();render();toast('手冊與紀錄已刪除');}
 if(id==='delete-reward-form'){await mutate(s=>{s.rewards=s.rewards.filter(r=>r.id!==form.dataset.id);});closeModal();toast('已移除獎勵，過往紀錄仍保留');}
 if(id==='start-family-form'){await mutate(s=>{s.children=[];s.events=[];s.demo=false;});selected=null;closeModal();childForm();}
 if(id==='backup-form'){
  const mode=form.dataset.mode;
  if(!recovery&&!unlocked())throw Error('請重新解鎖家長模式再進行備份。');
  if(mode==='export'){if(f.get('password')!==f.get('confirm'))throw Error('兩次備份密碼不相同');const data=await encryptBackup(state,String(f.get('password')));const url=URL.createObjectURL(new Blob([data],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=`小小集點園-${new Date().toISOString().slice(0,10)}.garden`;a.click();setTimeout(()=>URL.revokeObjectURL(url),60000);closeModal();toast('加密備份已下載，請妥善保存密碼');}
  else {const file=f.get('file');if(!file||file.size>15000000)throw Error('請選擇 15 MB 以內的加密備份');const restored=await decryptBackup(await file.text(),String(f.get('password')));if(!restored.pin||!await verifyPin(String(f.get('pin')),restored.pin))throw Error('備份中的家長密碼不正確，尚未匯入資料。');if(restored.lockUntil>Date.now())throw Error('這份備份的家長保護暫停尚未結束，請稍後再匯入。');if(!recovery&&!unlocked())throw Error('家長模式已上鎖，請重新解鎖再匯入。');restored.failures=0;restored.lockUntil=0;if(recovery)await recoverStore(restored);else await saveState(restored);state=restored;selected=state.children[0]?.id;draftStamp=null;cardPages.clear();recovery=false;sessionUntil=0;closeModal();navigate('home');toast('資料驗證完成，回憶接著延續！');}
 }
 }catch(e){formError(e);}finally{submitting=false;if(button?.isConnected)button.disabled=false;}
}
function celebrate(){if(matchMedia('(prefers-reduced-motion: reduce)').matches)return;const box=document.createElement('div');box.className='confetti';box.setAttribute('aria-hidden','true');box.innerHTML=Array.from({length:24},(_,i)=>`<i style="--x:${Math.random()*100}%;--delay:${Math.random()*.4}s;--color:${['#c9d9bb','#ebc86b','#dca8a2','#bab0d3'][i%4]};--rotate:${Math.random()*720}deg"></i>`).join('');document.body.append(box);setTimeout(()=>box.remove(),2200);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(b){e.preventDefault();action(b).catch(formError);}});
document.addEventListener('submit',e=>{if(e.target.closest('#modal-root')){e.preventDefault();submit(e.target);}});
document.addEventListener('change',e=>{if(e.target.id==='history-filter'){historyFilter=e.target.value;const viewport=viewState.capture(),list=$('.history-list');if(list?.getBoundingClientRect)list.style.minHeight=list.getBoundingClientRect().height+'px';$('#history-entries').innerHTML=historyRows(state.events.filter(x=>x.childId===active().id&&(e.target.value==='all'||x.kind===e.target.value)).slice().reverse());viewState.restore(viewport);}});
document.addEventListener('keydown',e=>{if(!$('#modal-root').firstElementChild)return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){const nodes=[...$('#modal-root').querySelectorAll('button:not(:disabled),input,select,textarea,a[href]')].filter(n=>n.offsetParent!==null),first=nodes[0],last=nodes.at(-1);if(!nodes.includes(document.activeElement)){e.preventDefault();viewState.focusNoScroll(e.shiftKey?last:first);return;}if(e.shiftKey&&document.activeElement===first){e.preventDefault();viewState.focusNoScroll(last);}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();viewState.focusNoScroll(first);}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden&&sessionUntil){sessionUntil=0;if(state)render();}});
setInterval(()=>{if(sessionUntil&&Date.now()>sessionUntil){sessionUntil=0;render();toast('家長模式已自動上鎖');}},1000);
async function boot(){try{if(!await ownWriter()){app.innerHTML='<div class="fatal"><span>✿</span><h1>集點園已在另一個分頁開啟</h1><p>為避免紀錄互相覆蓋，請使用原本分頁，或關閉它後重新整理。</p><button class="btn primary" onclick="location.reload()">重新整理</button></div>';return;}state=await initStore();selected=state.children[0]?.id;render();}catch(e){recovery=true;app.innerHTML=`<div class="fatal"><span>✿</span><h1>先保護好我們的小回憶</h1><p>${esc(e.message||'此瀏覽器無法開啟 IndexedDB，請使用支援本機儲存的瀏覽器。')}</p><button class="btn primary" data-action="import">${icon('upload')} 從加密備份還原</button></div>`;}}
boot();
